import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class TypeCheck_shouldTraverse_TriageGen1Test {

    private Compiler compiler;
    private JSTypeRegistry typeRegistry;
    private TypeCheck typeCheck;

    @Mock private NodeTraversal mockTraversal;
    @Mock private Node mockNode;
    @Mock private Node mockParent;
    @Mock private Scope mockScope;

    @Before
    public void setUp() {
        MockitoAnnotations.initMocks(this);
        compiler = createCompiler();
        typeRegistry = new JSTypeRegistry();
        typeRegistry.setBuiltinTypes();

        // Note: Using a subclass or spy might be needed if checkNoTypeCheckSection is final/private
        // For this test, we assume TypeCheck is instantiated via the provided constructor
        typeCheck = new TypeCheck(
            compiler,
            null,
            typeRegistry,
            CheckLevel.MEDIUM,
            CheckLevel.MEDIUM
        );
    }

    @Test
    public void testShouldTraverse_NotFunction() {
        when(mockNode.getType()).thenReturn(Token.VAR);

        boolean result = typeCheck.shouldTraverse(mockTraversal, mockNode, mockParent);

        assertTrue(result);
    }

    @Test
    public void testShouldTraverse_Function_NoConflict() {
        when(mockNode.getType()).thenReturn(Token.FUNCTION);

        // Mock function name child
        Node mockNameNode = mock(Node.class);
        when(mockNode.getFirstChild()).thenReturn(mockNameNode);
        when(mockNameNode.getString()).thenReturn("myFunc");

        // Mock JSType
        JSType mockFuncType = mock(FunctionType.class);
        when(mockNode.getJSType()).thenReturn(mockFuncType);

        // Mock Scope
        when(mockTraversal.getScope()).thenReturn(mockScope);
        when(mockScope.isDeclared("myFunc", false)).thenReturn(false);

        boolean result = typeCheck.shouldTraverse(mockTraversal, mockNode, mockParent);

        assertTrue(result);
    }

    @Test
    public void testShouldTraverse_Function_EmptyName() {
        when(mockNode.getType()).thenReturn(Token.FUNCTION);

        Node mockNameNode = mock(Node.class);
        when(mockNode.getFirstChild()).thenReturn(mockNameNode);
        when(mockNameNode.getString()).thenReturn(""); // Empty string

        when(mockNode.getJSType()).thenReturn(mock(FunctionType.class));
        when(mockTraversal.getScope()).thenReturn(mockScope);

        boolean result = typeCheck.shouldTraverse(mockTraversal, mockNode, mockParent);

        assertTrue(result);
    }

    @Test
    public void testShouldTraverse_Function_NullName() {
        when(mockNode.getType()).thenReturn(Token.FUNCTION);

        Node mockNameNode = mock(Node.class);
        when(mockNode.getFirstChild()).thenReturn(mockNameNode);
        when(mockNameNode.getString()).thenReturn(null);

        when(mockNode.getJSType()).thenReturn(mock(FunctionType.class));
        when(mockTraversal.getScope()).thenReturn(mockScope);

        boolean result = typeCheck.shouldTraverse(mockTraversal, mockNode, mockParent);

        assertTrue(result);
    }

    @Test
    public void testShouldTraverse_Function_ConflictFound() {
        when(mockNode.getType()).thenReturn(Token.FUNCTION);

        // Function name
        Node mockNameNode = mock(Node.class);
        when(mockNode.getFirstChild()).thenReturn(mockNameNode);
        String funcName = "conflictVar";
        when(mockNameNode.getString()).thenReturn(funcName);

        // Function type
        FunctionType functionType = mock(FunctionType.class);
        when(mockNode.getJSType()).thenReturn(functionType);

        // Scope setup: exists in scope but is NOT a FunctionType
        when(mockTraversal.getScope()).thenReturn(mockScope);
        when(mockScope.isDeclared(funcName, false)).thenReturn(true);

        Node mockVarNode = mock(Node.class);
        JSType nonFunctionType = mock(JSType.class); 
        when(mockScope.getVar(funcName)).thenReturn(mockVarNode);
        when(mockVarNode.getType()).thenReturn(nonFunctionType);

        // We expect report to be called (if report is accessible/mockable)
        // Since report is likely a method in TypeCheck, we check the return value
        boolean result = typeCheck.shouldTraverse(mockTraversal, mockNode, mockParent);

        assertTrue(result);
        // Verification of report() would happen here if report is a mockable dependency
    }

    @Test
    public void testShouldTraverse_Function_ConflictResolvedByType() {
        when(mockNode.getType()).thenReturn(Token.FUNCTION);

        Node mockNameNode = mock(Node.class);
        when(mockNode.getFirstChild()).thenReturn(mockNameNode);
        String funcName = "validFunc";
        when(mockNameNode.getString()).thenReturn(funcName);

        FunctionType functionType = mock(FunctionType.class);
        when(mockNode.getJSType()).thenReturn(functionType);

        when(mockTraversal.getScope()).thenReturn(mockScope);
        when(mockScope.isDeclared(funcName, false)).thenReturn(true);

        Node mockVarNode = mock(Node.class);
        when(mockScope.getVar(funcName)).thenReturn(mockVarNode);
        // If it IS a FunctionType, the warning should NOT be reported
        when(mockVarNode.getType()).thenReturn(functionType);

        boolean result = typeCheck.shouldTraverse(mockTraversal, mockNode, mockParent);

        assertTrue(result);
    }
}
